import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'gloss': ['lie down!, he lay down'], 'forms': ['letgayā', 'leṭgɔ', 'līṭɨgyɔ', 'leṭgeya', 'leṭīgyo', 'leṭgayo'], 'evidence': 'The whole compound has lie down + gone. Turner lēṭyati explicitly gives regional leṭ- lie down, and gata supplies the gay-/ga- past of go. Both constituents are recorded in order, including the local raised līṭ- vowel.', 'citation': 'CDIAL[11109];CDIAL[4008]', 'components': ['11109', '4008']}, {'gloss': ['lie down!, he lay down'], 'forms': ['leṭījāo', 'leṭjā'], 'evidence': 'The complete imperative has lie down + go: regional leṭ- from Turner lēṭyati and jā- from yāti. Both lexical constituents are represented in order.', 'citation': 'CDIAL[11109];CDIAL[10452]', 'components': ['11109', '10452']}, {'gloss': ['lie down!, he lay down'], 'forms': ['loṭgo', 'lūāṭgo', 'lūaṭgɔ', 'luɔtgɔ', 'luṭīgīo', 'loḍagyɔ', 'loṭgayo', 'lūṭṭūgūyū', 'nūṭṭigoi-nū'], 'evidence': 'Qualified reflexes of the loṭ-/luṭ- roll/lie family plus the gay- gone auxiliary. Turner *lōrtati explicitly includes Pk loṭṭai rolls/sleeps and luṭṭai sleeps, with the unaspirated regional loṭ- series and Oriya noṭ- variant. The western survey geminates and n-initial variants are compared with this family without claiming that the Oriya variant is their immediate ancestor. Both constituents are included; extra hū/hūi auxiliary clauses are excluded.', 'citation': 'CDIAL[11156];CDIAL[4008]', 'components': ['11156', '4008']}, {'gloss': ['lie down!, he lay down'], 'forms': ['loṭīja', 'lūṭījā', 'loḍjā', 'loṭjaū', 'loṭjā', 'lūṭṭijā', 'nūṭṭijā', 'nūṭṭijo'], 'evidence': 'The complete imperative consists of roll/lie down + go. The first member is compared with Turner *lōrtati (Pk loṭṭai/luṭṭai sleep; regional loṭ- and n-initial noṭ-); the second is jā-/jo go from yāti. The n-initial western forms are qualified comparative members of this family, preserving the source spelling rather than asserting a direct Oriya borrowing.', 'citation': 'CDIAL[11156];CDIAL[10452]', 'components': ['11156', '10452']}, {'gloss': ['lie down!, he lay down'], 'forms': ['lɔṭyo', 'lūṭ, lūṭyū'], 'evidence': 'The unaspirated loṭ-/luṭ- lie-down verb matches Turner *lōrtati, including Pk loṭṭai rolls/sleeps and luṭṭai sleeps. These are a simple past or imperative/past pair of the same verb; no independent go auxiliary is present.', 'citation': 'CDIAL[11156]', 'parent': '11156'}, {'gloss': ['lie down!, he lay down'], 'forms': ['so gɔ', 'so gayā', 'sūgayɔ', 'sɔgyɔ', 'sovgeya', 'soygayo'], 'evidence': 'The complete compound is sleep/lie down + gone. Turner supplies the sov-/so- sleep family under svapiti and the gay- past of go under gata. Both constituents are linked in order, including the local vowel variants.', 'citation': 'CDIAL[13902];CDIAL[4008]', 'components': ['13902', '4008']}, {'gloss': ['lie down!, he lay down'], 'forms': ['soyja'], 'evidence': 'The entire imperative is sleep/lie down + go: svapiti through soy-/so- plus yāti through jā-. Both ordered components are saved.', 'citation': 'CDIAL[13902];CDIAL[10452]', 'components': ['13902', '10452']}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   x=dict(record=r,citation=g['citation'],evidence=g['evidence'],family=i)
   if 'components' in g:x['components']=g['components']
   else:x.update(parent=g['parent'],kind=g.get('kind','reflex'))
   a.append(x)
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
(P/'pass067-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass067-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g.get('parent',g.get('components')),sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
